update public.study_materials s set quiz=(select jsonb_agg(case when x->>'q' ilike '%inss retido%' and not coalesce(x->>'why','') like '%Exemplo cotidiano:%' then jsonb_set(x,'{why}',to_jsonb(coalesce(x->>'why','') || ' Exemplo cotidiano: salário bruto combinado de R$ 1.000, retenção hipotética de R$ 100: o empregado recebe R$ 900 e R$ 100 vão ao INSS. O patrão paga ainda R$ 200 de contribuição própria. Total devido: R$ 1.200, sendo R$ 900 ao empregado e R$ 300 ao INSS. A retenção não aumenta o salário bruto. Macete: retido desconta; patronal acrescenta.')) when (x->>'q' ilike '%goodwill%' and x->>'q' ilike any(array['%revert%','%estorno%','%reversão%'])) and not coalesce(x->>'why','') like '%Exemplo cotidiano:%' then jsonb_set(x,'{why}',to_jsonb(coalesce(x->>'why','') || ' Exemplo cotidiano: uma padaria comprada por R$ 150 mil com ativos líquidos de R$ 100 mil gera goodwill de R$ 50 mil. Após perda de R$ 20 mil, restam R$ 30 mil. Mesmo que volte a prosperar, não se estorna a perda. CPC 01, itens 124–125. Macete: goodwill perdeu, não reverte.')) when x->>'q' ilike '%compra vantajosa%' and not coalesce(x->>'why','') like '%Exemplo cotidiano:%' then jsonb_set(x,'{why}',to_jsonb(coalesce(x->>'why','') || ' Exemplo cotidiano: compra de 90% por R$ 300 mil, ativos líquidos de R$ 400 mil e não controladores de R$ 40 mil: ganho de R$ 60 mil. Antes de reconhecer no resultado, revisar ativos, passivos, não controladores, contraprestação e participação anterior, se houver. CPC 15, item 36.')) else x end order by ord) from jsonb_array_elements(s.quiz) with ordinality t(x,ord)),updated_at=now() where slug in ('pcac-2026-contabilidade-10-impairment-goodwill-reducao-valor-recuperavel','pcac-2026-contabilidade-18-folha-pagamento-encargos-inss-fgts') and jsonb_typeof(quiz)='array';